import { describe, it, expect } from "vitest";
import CNextMarkerDetector from "../CNextMarkerDetector";

describe("CNextMarkerDetector", () => {
  describe("the banner since the cnx rename (#2168)", () => {
    it("reads the source path from a generated header's banner", () => {
      const content = `/**
 * generated by cnx from: led.cnx
 * Header file for cross-language interoperability
 */`;
      expect(CNextMarkerDetector.findMarker(content)).toEqual({
        sourcePath: "led.cnx",
        line: 2,
        column: 26,
      });
    });

    it("counts a banner with no source path as generated, naming no source", () => {
      const content = `/**
 * generated by cnx
 */`;
      expect(CNextMarkerDetector.isCNextGenerated(content)).toBe(true);
      expect(CNextMarkerDetector.findMarker(content)).toBeNull();
    });

    it("does not take an ordinary header comment for a banner", () => {
      const content = `/**
 * Generated by hand for the cnx port
 */`;
      expect(CNextMarkerDetector.isCNextGenerated(content)).toBe(false);
      expect(CNextMarkerDetector.findMarker(content)).toBeNull();
    });

    it.each([
      [
        "prose that quotes the banner",
        "/* Thin wrapper over the API generated by cnx from: led.cnx */",
      ],
      ["a longer word ending in the text", "// regenerated by cnx nightly"],
      // cspell:ignore cnxgen
      ["the text running into a longer name", "/* generated by cnxgen 2.1 */"],
    ])("does not take %s for a banner", (_label, content) => {
      expect(CNextMarkerDetector.isCNextGenerated(content)).toBe(false);
      expect(CNextMarkerDetector.findMarker(content)).toBeNull();
    });
  });

  describe("the banner from before the cnx rename (TODO(#2183))", () => {
    it("still reads the source path from the old banner", () => {
      const content = `/**
 * Generated by C-Next Transpiler from: led.cnx
 * Header file for cross-language interoperability
 */`;
      expect(CNextMarkerDetector.findMarker(content)).toEqual({
        sourcePath: "led.cnx",
        line: 2,
        column: 40,
      });
    });

    it("still counts the old banner with no source path as generated", () => {
      const content = `/**
 * Generated by C-Next Transpiler
 */`;
      expect(CNextMarkerDetector.isCNextGenerated(content)).toBe(true);
      expect(CNextMarkerDetector.findMarker(content)).toBeNull();
    });
  });

  describe("findMarker", () => {
    it("should extract source path from valid marker", () => {
      const content = `/**
 * generated by cnx from: led.cnx
 * Header file for cross-language interoperability
 */`;
      expect(CNextMarkerDetector.findMarker(content)?.sourcePath).toBe(
        "led.cnx",
      );
    });

    it("should return null for header without marker", () => {
      const content = `/**
 * Some other header
 */
#ifndef FOO_H
#define FOO_H`;
      expect(CNextMarkerDetector.findMarker(content)).toBeNull();
    });

    it("should handle paths with directories", () => {
      const content = `/**
 * generated by cnx from: ../lib/utils.cnx
 */`;
      expect(CNextMarkerDetector.findMarker(content)?.sourcePath).toBe(
        "../lib/utils.cnx",
      );
    });
  });

  describe("findMarker position", () => {
    it("places the recorded name at its line and column", () => {
      // #1542: E0509 is reported here, so the name's own position is the
      // contract -- line 1-based, column 0-based, as every diagnostic's.
      const content = `#ifndef LED_H
/**
 * generated by cnx from: led.cnx
 */`;
      expect(CNextMarkerDetector.findMarker(content)).toEqual({
        sourcePath: "led.cnx",
        line: 3,
        column: 26,
      });
    });

    it("places a marker on the first line at line 1", () => {
      expect(
        CNextMarkerDetector.findMarker("// generated by cnx from: a.cnx"),
      ).toEqual({ sourcePath: "a.cnx", line: 1, column: 26 });
    });
  });

  describe("isCNextGenerated", () => {
    it("should return true for C-Next generated header", () => {
      const content = `/**
 * generated by cnx from: led.cnx
 */`;
      expect(CNextMarkerDetector.isCNextGenerated(content)).toBe(true);
    });

    it("should return false for non-generated header", () => {
      const content = `#ifndef FOO_H
#define FOO_H`;
      expect(CNextMarkerDetector.isCNextGenerated(content)).toBe(false);
    });
  });
});
